const utils = require("./../../util/utils");
const logger = require("./../../util/logger");

const moduleName = "NODE-CRON";

const moduleInfo = {
    functions: [
        {
            functionName: ["schedule"],
            wrapper: scheduleWrapper,
            component: moduleName
        }
    ]
};

function scheduleWrapper(actual) {
    return function () {
        if (utils.isFunction(arguments[1])) {
            const opts = arguments[2] && typeof arguments[2] === "object" ? arguments[2] : {};
            arguments[1] = scheduledJobWrapper(arguments[1], arguments[0], opts.name);
        }
        return actual.apply(this, arguments);
    };
}

function scheduledJobWrapper(actual, cronExpression, taskName) {
    return function () {
        // Create a meaningful transaction name including the cron expression when possible
        const txnName = "Cron-Job:" + (utils.isNonEmptyString(cronExpression) ? cronExpression : "unknown");
        const self = this;
        const outerArgs = arguments;

        if (!apmInsightAgentInstance.getConfig().isDataExporterEnabled()) {
            let th = utils.getGenericThreshold(txnName);
            if (!th.isBgTxnTrackingEnabled()) {
                logger.info("NODE-CRON: bg txn tracking disabled for: " + txnName);
                return actual.apply(self, outerArgs);
            }
            if (!th.isBgTxnTraceEnabled()) {
                logger.info("NODE-CRON: bg txn trace disabled for: " + txnName);
            }
        }

        let jobFunc = function () {
            apmInsightAgentInstance.addParameter("cron.expression", txnName);
            if (utils.isNonEmptyString(taskName)) {
                apmInsightAgentInstance.addParameter("cron.taskName", taskName);
            }
            // outerArgs[0] is the scheduled fire date passed by node-cron to the callback
            if (outerArgs && outerArgs[0] instanceof Date) {
                apmInsightAgentInstance.addParameter("cron.scheduledAt", outerArgs[0].toISOString());
            }
            let result;
            try {
                result = actual.apply(self, outerArgs);
                apmInsightAgentInstance.endApiTxn();
            } catch (err) {
                apmInsightAgentInstance.endApiTxn(err);
                err.apmAgentHandled = true;
                throw err;
            }
            return result;
        }

        // Set the function name so startApiTransaction uses it as the root tracker name
        if (utils.isNonEmptyString(taskName)) {
            Object.defineProperty(jobFunc, "name", { value: taskName, configurable: true });
        }

        return apmInsightAgentInstance.startApiTransaction(txnName, jobFunc, true);
    };
}

module.exports = moduleInfo;